  info('module', `${stageCol(enc.moduleRef)}`);
  info('modality', `${posColor(enc.modality)}`);
  info('arc', `${posColor(posTag)}  ${chalk.dim('difficulty:' + enc.difficulty.toFixed(2) + ' pr:' + enc.priority.toFixed(3))}`);
