/** Forward-compatible migration. Currently there is only v1. */
function migrate(input: Partial<SaveData>): SaveData {
  return {
    ...DEFAULT_SAVE,
    ...input,
    cognitive: { ...DEFAULT_SAVE.cognitive, ...(input.cognitive ?? {}) },
    version: CURRENT_VERSION,
  };
